        for name, meta in run['datasets'].items():
            path = Path(meta['path'])
            if _sha(path) != meta['sha256']:
                raise ServiceError(409, 'DATASET_CHANGED', 'Uma saída imutável foi alterada; inicie novo run.', [{'dataset': name}])
