            self.db.execute('INSERT INTO wf_decisions(run_id,exception_id,data) VALUES (?,?,?)', (ident, exception_id, _json(after)))
            self._audit(ident, 'exception_decision', actor, {'before': before, 'after': exception, 'justificativa': reason})
