                names = [f'Tarvo_Data_Pack_{period}', f'Tarvo_Data_Pack_{month_names[int(period[5:])-1]}{period[:4]}']
                default_periods = set()
                if self.source_dir.is_dir():
                    try:
                        existing = load_data(self.source_dir)
